package cn.balltv.portal;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.util.*;
public class SignalProbeTest {
 static byte[] ts(int stream){byte[] b=new byte[188*3];for(int p=0;p<b.length;p+=188)b[p]=0x47;b[4]=0;b[5]=0;b[6]=1;b[7]=(byte)stream;return b;}
 static byte[] flv(int type,int packet,int lastTime)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(new byte[]{'F','L','V',1,5,0,0,0,9,0,0,0,0});for(int t:new int[]{0,lastTime}){byte[] tag={ (byte)type,0,0,11,(byte)(t>>16),(byte)(t>>8),(byte)t,0,0,0,0};out.write(tag);out.write(new byte[]{0x17,(byte)packet,0,0,0,0,0,0,2,0x65,1});out.write(new byte[]{0,0,0,22});}return out.toByteArray();}
 @Test public void requiresVideoPesNotJustTransportSync(){assertTrue(SignalProbe.tsVideo(ts(0xe0)));assertFalse(SignalProbe.tsVideo(ts(0xc0)));assertFalse(SignalProbe.tsVideo("<html>200 OK</html>".getBytes()));}
 @Test public void flvNeedsTwoMovingVideoFramesNotHeaderOrAudioOrCodecConfig()throws Exception{assertTrue(SignalProbe.flvVideo(flv(9,1,40)));assertFalse(SignalProbe.flvVideo(flv(8,1,40)));assertFalse(SignalProbe.flvVideo(flv(9,0,40)));assertFalse(SignalProbe.flvVideo(flv(9,1,0)));}
 @Test public void masterPlaylistResolvesRelativeVariantAndActualMedia()throws Exception{Map<String,byte[]> data=new HashMap<String,byte[]>();String root="https://example.org/live/master.m3u8";data.put(root,"#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=500000\nhd/list.m3u8\n".getBytes("UTF-8"));data.put("https://example.org/live/hd/list.m3u8","#EXTM3U\n#EXT-X-TARGETDURATION:6\n#EXT-X-MEDIA-SEQUENCE:100\n#EXTINF:6,\n../segment.ts?sig=test\n".getBytes("UTF-8"));data.put("https://example.org/live/segment.ts?sig=test",ts(0xe0));List<String> requests=new ArrayList<String>();SignalProbe.Result r=SignalProbe.check(root,"https://site.example/",(url,ref,max,deadline)->{requests.add(url);if(!data.containsKey(url))throw new IOException("bad resolution");return data.get(url);});assertEquals(3,requests.size());assertTrue(r.fingerprint.contains("100:/live/segment.ts"));}
 @Test public void endedPlaylistRejectedBeforeFetchingStaleMedia()throws Exception{int[] count={0};try{SignalProbe.check("https://example.org/x.m3u8","",(u,r,m,d)->{count[0]++;return "#EXTM3U\n#EXTINF:6,\nold.ts\n#EXT-X-ENDLIST".getBytes("UTF-8");});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("结束"));}assertEquals(1,count[0]);}
 @Test(expected=IOException.class) public void htmlHttpSuccessIsNotPlayableMedia()throws Exception{SignalProbe.check("https://example.org/live.flv","",(u,r,m,d)->"<html>stream expired</html>".getBytes("UTF-8"));}
 @Test(expected=IOException.class) public void emptyPlaylistIsRejected()throws Exception{SignalProbe.check("https://example.org/live.m3u8","",(u,r,m,d)->"#EXTM3U\n#EXT-X-TARGETDURATION:6".getBytes("UTF-8"));}
}
